export interface PlatformLimit {
  platform: string;
  dailyLimit: number;
  appliedToday: number;
  lastAppliedAt: Date | null;
  minIntervalMinutes: number;
}

export class RateGovernor {
  private limits = new Map<string, PlatformLimit>([
    ["linkedin", { platform: "linkedin", dailyLimit: 12, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 20 }],
    ["naukri", { platform: "naukri", dailyLimit: 15, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 15 }],
    ["shine", { platform: "shine", dailyLimit: 15, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 15 }],
    ["foundit", { platform: "foundit", dailyLimit: 12, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 20 }],
    ["workday", { platform: "workday", dailyLimit: 8, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 30 }],
    ["greenhouse", { platform: "greenhouse", dailyLimit: 8, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 30 }],
  ]);

  private globalDailyLimit = 30;
  private startHourIST = 7; // 7 AM
  private endHourIST = 22;  // 10 PM

  private async loadState(): Promise<{
    globalAppliedToday: number;
    platformApplies: Record<string, { appliedToday: number; lastAppliedAt: string | null }>;
    lastResetDate: string | null;
  }> {
    const store = getStore();
    const data = await store.get("rate_governor_state") as any;
    const todayStr = new Date().toDateString();

    if (!data || data.lastResetDate !== todayStr) {
      return {
        globalAppliedToday: 0,
        platformApplies: {},
        lastResetDate: todayStr,
      };
    }
    return data;
  }

  private async saveState(state: any): Promise<void> {
    const store = getStore();
    await store.set("rate_governor_state", state);
  }

  /**
   * Determine if an application can be sent.
   */
  async canApply(platform: string): Promise<{ allowed: boolean; reason?: string }> {
    // Verify hours of operation in India Standard Time
    const now = new Date();
    // Offset for UTC to IST (+5:30)
    const istOffset = 5.5 * 60 * 60 * 1000;
    const istTime = new Date(now.getTime() + istOffset);
    const hour = istTime.getUTCHours();

    if (hour < this.startHourIST || hour >= this.endHourIST) {
      return { allowed: false, reason: `Outside permitted hours of operations (7 AM - 10 PM IST)` };
    }

    const state = await this.loadState();

    if (state.globalAppliedToday >= this.globalDailyLimit) {
      return { allowed: false, reason: `Reached global daily application threshold (${this.globalDailyLimit})` };
    }

    const platformLimit = this.limits.get(platform);
    if (!platformLimit) return { allowed: true };

    const savedPlatformState = state.platformApplies[platform] || { appliedToday: 0, lastAppliedAt: null };

    if (savedPlatformState.appliedToday >= platformLimit.dailyLimit) {
      return { allowed: false, reason: `Reached daily limits for ${platform} (${platformLimit.dailyLimit})`

import { createLLM, getStore, DEFAULT_LLM_CONFIG, type LLMConfig } from "@superjob/core";
import { fetchEmails } from "./imap-client.js";
import { classifyEmail } from "./classifiers/classifier.js";
import { syncEmailToTracker } from "./tracker-sync.js";
import type { EmailScanResult, EmailUpdate, ImapConfig, JobEmail } from "./types.js";

export interface MonitorHooks {
  onFetch?: (count: number) => void;
  onClassify?: (email: JobEmail) => void;
  onUpdate?: (update: EmailUpdate) => void;
}

export interface MonitorConfig { imap: ImapConfig; llm?: LLMConfig; sinceDays?: number; maxScan?: number }

export async function scanInbox(config: MonitorConfig, hooks: MonitorHooks = {}): Promise<EmailScanResult> {
  let llmConfig = config.llm;
  if (!llmConfig) {
    const stored = await getStore().get<Partial<LLMConfig>>("llmConfig");
    llmConfig = { ...DEFAULT_LLM_CONFIG, ...(stored ?? {}) };
  }
  const llm = createLLM(llmConfig);
  const rawEmails = await fetchEmails({ ...config.imap, sinceDays: config.sinceDays ?? 7, maxScan: config.maxScan ?? 100 });
  hooks.onFetch?.(rawEmails.length);
  if (rawEmails.length === 0) return { scanned: 0, classified: 0, byCategory: {}, updates: [] };

  const updates: EmailUpdate[] = [];
  const byCategory: Record<string, number> = {};
  let classified = 0;

  for (const raw of rawEmails) {
    const email = await classifyEmail(raw, llm);
    if (email.category === "irrelevant") continue;
    classified++;
    byCategory[email.category] = (byCategory[email.category] ?? 0) + 1;
    hooks.onClassify?.(email);
    const update = await syncEmailToTracker(email);
    if (update.matchedApplication || update.created) { updates.push(update); hooks.onUpdate?.(update); }
  }
  return { scanned: rawEmails.length, classified, byCategory, updates };
}

export interface WatchHandle { stop: () => void; scanCount: () => number }

export function watchInbox(config: MonitorConfig, intervalMs: number, hooks: MonitorHooks & { onScanComplete?: (r: EmailScanResult) => void; onError?: (e: Error) => void } = {}): WatchHandle {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let scans = 0; let stopped = false;
  const run = async () => {
    if (stopped) return; scans++;
    try { const r = await scanInbox(config, hooks); hooks.onScanComplete?.(r); }
    catch (e) { hooks.onError?.(e instanceof Error ? e : new Error(String(e))); }
    if (!stopped) timer = setTimeout(run, intervalMs);
  };
  const shutdown = () => { stopped = true; if (timer) clearTimeout(timer); };
  process.on("SIGTERM", shutdown); process.on("SIGINT", shutdown);
  void run();
  return { stop: shutdown, scanCount: () => scans };
}

