      naukri: ["@naukri.com", "@naukri.org", "naukriemail.com"],
      linkedin: ["@linkedin.com", "@e.linkedin.com"],
      shine: ["@shine.com"],
      foundit: ["@foundit.in", "@foundit.sg", "@monsterindia.com"],
    };

    const domains = whitelist[platform.toLowerCase()];
    if (!domains) return true; // Fallback to allow if platform not whitelisted explicitly

    return domains.some(domain => lowerFrom.endsWith(domain) || lowerFrom.includes(domain));
  }

