export interface PlatformLimit {
  platform: string;
  dailyLimit: number;
  appliedToday: number;
  lastAppliedAt: Date | null;
  minIntervalMinutes: number;
}

export class RateGovernor {
  private limits = new Map<string, PlatformLimit>([
    ["linkedin", { platform: "linkedin", dailyLimit: 12, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 20 }],
    ["naukri", { platform: "naukri", dailyLimit: 15, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 15 }],
    ["shine", { platform: "shine", dailyLimit: 15, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 15 }],
    ["foundit", { platform: "foundit", dailyLimit: 12, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 20 }],
    ["workday", { platform: "workday", dailyLimit: 8, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 30 }],
    ["greenhouse", { platform: "greenhouse", dailyLimit: 8, appliedToday: 0, lastAppliedAt: null, minIntervalMinutes: 30 }],
  ]);

  private globalDailyLimit = 30;
  private startHourIST = 7; // 7 AM
  private endHourIST = 22;  // 10 PM

  private async loadState(): Promise<{
    globalAppliedToday: number;
    platformApplies: Record<string, { appliedToday: number; lastAppliedAt: string | null }>;
    lastResetDate: string | null;
  }> {
    const store = getStore();
    const data = await store.get("rate_governor_state") as any;
    const todayStr = new Date().toDateString();

    if (!data || data.lastResetDate !== todayStr) {
      return {
        globalAppliedToday: 0,
        platformApplies: {},
        lastResetDate: todayStr,
      };
    }
    return data;
  }

  private async saveState(state: any): Promise<void> {
    const store = getStore();
    await store.set("rate_governor_state", state);
  }

  /**
   * Determine if an application can be sent.
   */
  async canApply(platform: string): Promise<{ allowed: boolean; reason?: string }> {
    // Verify hours of operation in India Standard Time
    const now = new Date();
    // Offset for UTC to IST (+5:30)
    const istOffset = 5.5 * 60 * 60 * 1000;
    const istTime = new Date(now.getTime() + istOffset);
    const hour = istTime.getUTCHours();

    if (hour < this.startHourIST || hour >= this.endHourIST) {
      return { allowed: false, reason: `Outside permitted hours of operations (7 AM - 10 PM IST)` };
    }

    const state = await this.loadState();

    if (state.globalAppliedToday >= this.globalDailyLimit) {
      return { allowed: false, reason: `Reached global daily application threshold (${this.globalDailyLimit})` };
    }

    const platformLimit = this.limits.get(platform);
    if (!platformLimit) return { allowed: true };

    const savedPlatformState = state.platformApplies[platform] || { appliedToday: 0, lastAppliedAt: null };

    if (savedPlatformState.appliedToday >= platformLimit.dailyLimit) {
      return { allowed: false, reason: `Reached daily limits for ${platform} (${platformLimit.dailyLimit})`

