  const byCategory: Record<string, number> = {};
  let classified = 0;

  for (const raw of rawEmails) {
    const email = await classifyEmail(raw, llm);
    if (email.category === "irrelevant") continue;
    classified++;
    byCategory[email.category] = (byCategory[email.category] ?? 0) + 1;
    hooks.onClassify?.(email);
    const update = await syncEmailToTracker(email);
    if (update.matchedApplication || update.created) { updates.push(update); hooks.onUpdate?.(update); }
  }
  return { scanned: rawEmails.length, classified, byCategory, updates };
}

export interface WatchHandle { stop: () => void; scanCount: () => number }

export function watchInbox(config: MonitorConfig, intervalMs: number, hooks: MonitorHooks & { onScanComplete?: (r: EmailScanResult) => void; onError?: (e: Error) => void } = {}): WatchHandle {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let scans = 0; let stopped = false;
  const run = async () => {
    if (stopped) return; scans++;
    try { const r = await scanInbox(config, hooks); hooks.onScanComplete?.(r); }
    catch (e) { hooks.onError?.(e instanceof Error ? e : new Error(String(e))); }
    if (!stopped) timer = setTimeout(run, intervalMs);
  };
  const shutdown = () => { stopped = true; if (timer) clearTimeout(timer); };
  process.on("SIGTERM", shutdown); process.on("SIGINT", shutdown);
  void run();
  return { stop: shutdown, scanCount: () => scans };
}

import { ImapFlow } from "imapflow";
import type { ImapConfig } from "./types.js";
import { simpleParser } from "mailparser";

export interface RawEmail {
  messageId: string;
  from: string;
  fromName: string;
  subject: string;
  text: string;
  html: string;
  date: Date;
}

export async function fetchEmails(config: ImapConfig): Promise<RawEmail[]> {
  const client = new ImapFlow({
    host: config.host,
    port: config.port,
    secure: config.tls,
    auth: { user: config.user, pass: config.password },
    logger: false,
  });

  const emails: RawEmail[] = [];

  await client.connect();
  try {
    const lock = await client.getMailboxLock(config.mailbox ?? "INBOX");
    try {
      const since = new Date();
      since.setDate(since.getDate() - (config.sinceDays ?? 7));

      const searchResult: unknown = await client.search({ since }, { uid: true });
      const uids: number[] = Array.isArray(searchResult) ? (searchResult as number[]) : [];
      const toFetch = uids.slice(-(config.maxScan ?? 100));

      if (toFetch.length === 0) return [];

      for (const uid of toFetch) {
        const msg: unknown = await client.fetchOne(uid, { source: true, envelope: true }, { uid: true });
        const source = (msg as Record<string, unknown>)?.source;
        if (!source) continue;

        try {
          const parsed = await simpleParser(source as Buffer);
          emails.push({
            messageId: parsed.messageId ?? String(uid),
            from: parsed.from?.value?.[0]?.address ?? "",
            fromName: parsed.from?.value?.[0]?.name ?? "",
            subject: parsed.subject ?? "(no subject)",
            text: parsed.text ?? "",
            html: typeof parsed.html === "string" ? parsed.html : "",
            date: parsed.date ?? new Date(),
          });
        } catch {
          continue;
        }
      }
    } finally {
      lock.release();
    }
  } finally {
    await client.logout().catch(() => {});
  }

  return emails;
}

export async function testConnection(config: ImapConfig): Promise<{ ok: boolean; error?: string; info?: string }> {
  const client = new ImapFlow({
    host: config.host,
    port: config.port,
    secure: config.tls,
    auth: { user: config.user, pass: config.password },
    logger: false,
  });

  try {
    await client.connect();
    const status = await client.status(config.mailbox ?? "INBOX", { messages: true, unseen: true });
    await client.logout();
    return { ok: true, info: `${status.messages} messages (${status.unseen} unseen)` };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}

