    password: "",
    label: cred.label?.trim(),
    updatedAt: Date.now(),
  };
  if (vaultPassphrase && cred.password) {
    entry.passwordEnc = await encryptText(cred.password, vaultPassphrase);
  } else {
    entry.password = cred.password;
  }
