  filled: number;
  skipped: number;
  details: { label: string; ok: boolean; value: string }[];
  aiAnswered: number;
}

export async function fillForm(
  page: Page,
  fields: ScannedField[],
  lookup: ProfileLookup,
  profile: Profile,
  llm: LLMClient,
  delayMs = 0
): Promise<FillOutcome> {
  let filled = 0;
  let skipped = 0;
  let aiAnswered = 0;
  const details: { label: string; ok: boolean; value: string }[] = [];

  for (const field of fields) {
