import { extractKeywords, tokenize, type Keyword } from "./matcher.js";

export interface AtsAnalysis {
  /** keywords present in the JD that are NOT in the resume (the leaks) */
  gaps: Keyword[];
  /** keywords that ARE well-covered */
  covered: Keyword[];
  /** readability / structure flags */
  warnings: string[];
  /** an ATS-readability score 0..100 */
  score: number;
}

export function analyzeATS(
  resumeText: string,
  jobDescription: string
): AtsAnalysis {
  const jdKeywords = extractKeywords(jobDescription, 30);
  const resumeTokens = new Set(tokenize(resumeText));

  const gaps: Keyword[] = [];
  const covered: Keyword[] = [];
  for (const kw of jdKeywords) {
    if (resumeTokens.has(kw.term)) covered.push(kw);
    else gaps.push(kw);
  }

  const warnings: string[] = [];
  const plain = resumeText.trim();
  if (plain.length < 200) warnings.push("Resume text is very short — ATS may read it as incomplete.");
  if (!/@/i.test(plain)) warnings.push("No email detected.");
  if ((plain.match(/\n/g) ?? []).length < 8) warnings.push("Few line breaks — structure may be hard to parse.");
  if (/https?:\/\//i.test(plain) === false) warnings.push("No URLs — consider adding LinkedIn/portfolio links.");

  const ratio = jdKeywords.length === 0 ? 0 : covered.length / jdKeywords.length;
  const score = Math.round(ratio * 100);

  return { gaps, covered, warnings, score };
}

/**
 * Produce a list of suggested bullet insertions to close ATS gaps.
 * Pure string suggestions — no LLM. The LLM rewriter in cover-letter/llm
 * layers on top of this when available.
 */
export function suggestInsertions(analysis: AtsAnalysis): string[] {
  return analysis.gaps
    .slice(0, 8)
    .map((g) => `Consider adding concrete experience using: "${g.term}".`);
}

