/**
 * Generate a tailored cover letter.
 *  - Uses the LLM client when configured.
 *  - Falls back to a deterministic, perfectly-readable template when no LLM
 *    is available (so the feature still works offline / with provider "none").
 */
export async function generateCoverLetter(
  job: Pick<Job, "title" | "company" | "description">,
  profile: Profile,
  llm: LLMClient
): Promise<{ text: string; source: "llm" | "template" }> {
  if (!llm.isAvailable()) {
    return { text: templateCoverLetter(job, profile), source: "template" };
  }

  const system =
    "You are an expert career writer. Write concise, specific, human-sounding cover letters. " +
    "Never use clichés like 'I am writing to apply'. Never invent experience the candidate doesn't have. " +
    "Reference concrete bullet points from the candidate's resume that map to the job requirements. " +
    "Keep it under 220 words and 4 paragraphs.";

  const user = `JOB
Title: ${job.title}
Company: ${job.company}
Description:
${job.description.slice(0, 3000)}

CANDIDATE
${profileToText(profile).slice(0, 4000)}

Write the cover letter now. Plain text, no subject line.`;

  try {
    const text = await llm.complete([
      { role: "system", content: system },
      { role: "user", content: user },
    ]);
    return { text: text.trim(), source: "llm" };
  } catch {
    return { text: templateCoverLetter(job, profile), source: "template" };
  }
}

export function templateCoverLetter(
  job: Pick<Job, "title" | "company" | "description">,
  profile: Profile
): string {
  const name = `${profile.firstName} ${profile.lastName}`.trim() || "Candidate";
  const topSkills = profile.skills.slice(0, 4).join(", ") || "my core skills";
  const headline =
    profile.experience[0]?.title
      ? `a ${profile.experience[0].title}`
      : "an experienced professional";
  return [
    `Hi ${job.company || "Hiring Team"},`,
    ``,
    `I'm excited to apply for the ${job.title || "role"}${
      job.company ? ` at ${job.company}` : ""
    }. As ${headline}, my work maps closely to what this role needs.`,
    ``,
    `A few specifics from my background that are relevant here:`,
    `- ${profile.experience[0]?.bullets?.[0] ?? `Hands-on work with ${topSkills}.`}`,
    `- ${profile.experience[0]?.bullets?.[1] ?? `Strong proficiency across ${topSkills}.`}`,
    ``,
    `I'd welcome the chance to discuss how I can contribute. Thank you for your time.`,
    ``,
    `Best,`,
    name,
  ].join("\n");
}

