      const html = await fetchHtml(url, { delayMs, proxyUrl: params?.proxyUrl });
      if (!html) break;

      // Strategy 1: parse JSON-LD structured data (most reliable)
      const jsonLdJobs = parseJsonLd(html, limit - jobs.length);
