        // Strategy 2: parse embedded MOZ_CONTAINERS / result cards
        const cardJobs = parseResultCards(html, limit - jobs.length);
        jobs.push(...cardJobs);
      }

      if (page < maxPages - 1) await sleep(delayMs);
    }

    return jobs.slice(0, limit);
  },
};

