  if (!text) return "";
  return text
    .replace(/\b(work_outline|expand_more|arrow_drop_down|search|close|add|delete|edit|info|warning|error|check|help_outline|help)\b/gi, "")
    .replace(/\s+/g, " ")
    .replace(/\?\s*$/, "?")
    .trim();
}

