    const istTime = new Date(now.getTime() + istOffset);
    const hour = istTime.getUTCHours();

    if (hour < this.startHourIST || hour >= this.endHourIST) {
      return { allowed: false, reason: `Outside permitted hours of operations (7 AM - 10 PM IST)` };
    }

    const state = await this.loadState();

