interface OTPResult {
  code: string;
  source: "email" | "timeout";
}

export class OTPInterceptor {
  private imapConfig: ImapConfig;
  private pollIntervalMs = 3000;
  private timeoutMs = 90000; // 90 seconds maximum wait

  constructor(imapConfig: ImapConfig) {
    this.imapConfig = imapConfig;
  }

  async waitForOTP(platform: string): Promise<OTPResult> {
    const startTime = Date.now();
    const deadline = startTime + this.timeoutMs;

    while (Date.now() < deadline) {
      try {
        // Fetch emails from the last day to be safe, then filter locally by arrival timestamp
        const recentEmails = await fetchEmails({
          ...this.imapConfig,
          sinceDays: 1,
          maxScan: 10,
        });

        // Filter emails that arrived after our start time
        const newEmails = recentEmails.filter((email) => email.date.getTime() >= startTime - 5000);

        for (const email of newEmails) {
          if (!this.isValidSender(email.from, platform)) {
            console.log(`OTP Interceptor: Skipped verification mail from unverified sender: ${email.from}`);
            continue;
          }
          const otp = this.extractOTPFromEmail(email.text || email.html, platform);
          if (otp) {
            return { code: otp, source: "email" };
          }
        }
      } catch (err) {
        // Log error and retry polling
        console.error("OTP IMAP poll error:", err);
      }

      await this.sleep(this.pollIntervalMs);
    }

    throw new Error(`OTP timeout: verification code not received for platform: ${platform}`);
  }

  private isValidSender(from: string, platform: string): boolean {
    if (!from) return false;
    const lowerFrom = from.toLowerCase();

    // Whitelisted domains per platform
    const whitelist: Record<string, string[]> = {
      naukri: ["@naukri.com", "@naukri.org", "naukriemail.com"],
      linkedin: ["@linkedin.com", "@e.linkedin.com"],
      shine: ["@shine.com"],
      foundit: ["@foundit.in", "@foundit.sg", "@monsterindia.com"],
    };

    const domains = whitelist[platform.toLowerCase()];
    if (!domains) return true; // Fallback to allow if platform not whitelisted explicitly

    return domains.some(domain => lowerFrom.endsWith(domain) || lowerFrom.includes(domain));
  }

  private extractOTPFromEmail(body: string, platform: string): string | null {
    if (!body) return null;

    const patterns = [
      /\b(\d{6})\b(?=.*(?:verification|verify|otp|code))/i,
      /(?:OTP|verification\s*code|otp\s*code|code|pin)[^\d]*(\d{4,8})/i,
      /(\d{6})\s*is\s*your/i,
      /use\s*(?:code|otp|verification)[:\s]+(\d{4,8})/i,
      platform === "naukri" ? /naukri.*?(\d{6})/i : null,
      platform === "linkedin" ? /linkedin.*?(\d{6})/i : null,
    ].filter((p): p is RegExp => p !== null);

    for (const pattern of patterns) {
      const match = body.match(pattern);

import { createLLM, getStore, DEFAULT_LLM_CONFIG, type LLMConfig } from "@superjob/core";
import { fetchEmails } from "./imap-client.js";
import { classifyEmail } from "./classifiers/classifier.js";
import { syncEmailToTracker } from "./tracker-sync.js";
import type { EmailScanResult, EmailUpdate, ImapConfig, JobEmail } from "./types.js";

export interface MonitorHooks {
  onFetch?: (count: number) => void;
  onClassify?: (email: JobEmail) => void;
  onUpdate?: (update: EmailUpdate) => void;
}

export interface MonitorConfig { imap: ImapConfig; llm?: LLMConfig; sinceDays?: number; maxScan?: number }

export async function scanInbox(config: MonitorConfig, hooks: MonitorHooks = {}): Promise<EmailScanResult> {
  let llmConfig = config.llm;
  if (!llmConfig) {
    const stored = await getStore().get<Partial<LLMConfig>>("llmConfig");
    llmConfig = { ...DEFAULT_LLM_CONFIG, ...(stored ?? {}) };
  }
  const llm = createLLM(llmConfig);
  const rawEmails = await fetchEmails({ ...config.imap, sinceDays: config.sinceDays ?? 7, maxScan: config.maxScan ?? 100 });
  hooks.onFetch?.(rawEmails.length);
  if (rawEmails.length === 0) return { scanned: 0, classified: 0, byCategory: {}, updates: [] };

  const updates: EmailUpdate[] = [];
  const byCategory: Record<string, number> = {};
  let classified = 0;

  for (const raw of rawEmails) {
    const email = await classifyEmail(raw, llm);
    if (email.category === "irrelevant") continue;
    classified++;
    byCategory[email.category] = (byCategory[email.category] ?? 0) + 1;
    hooks.onClassify?.(email);
    const update = await syncEmailToTracker(email);
    if (update.matchedApplication || update.created) { updates.push(update); hooks.onUpdate?.(update); }
  }
  return { scanned: rawEmails.length, classified, byCategory, updates };
}

export interface WatchHandle { stop: () => void; scanCount: () => number }

export function watchInbox(config: MonitorConfig, intervalMs: number, hooks: MonitorHooks & { onScanComplete?: (r: EmailScanResult) => void; onError?: (e: Error) => void } = {}): WatchHandle {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let scans = 0; let stopped = false;
  const run = async () => {
    if (stopped) return; scans++;
    try { const r = await scanInbox(config, hooks); hooks.onScanComplete?.(r); }
    catch (e) { hooks.onError?.(e instanceof Error ? e : new Error(String(e))); }
    if (!stopped) timer = setTimeout(run, intervalMs);
  };
  const shutdown = () => { stopped = true; if (timer) clearTimeout(timer); };
  process.on("SIGTERM", shutdown); process.on("SIGINT", shutdown);
  void run();
  return { stop: shutdown, scanCount: () => scans };
}

/**
 * Lightweight multi-agent framework.
 *
 * Inspired by CrewAI's role/goal/backstory model, but implemented natively in
 * TypeScript so it integrates with @superjob/core without a Python runtime.
 *
 * Design:
 *   - An Agent has a role, a goal, and an execute() method.
 *   - Agents communicate through a shared Blackboard (read context, write results).
 *   - A Crew runs agents sequentially (or in stages), passing the blackboard along.
 *   - Each agent can use tools (functions it's allowed to call) and the LLM.
 *
 * This is deliberately framework-free so the same agents run in the CLI,
 * in Docker, or embedded in the dashboard.
 */
import type { ChatMessage, Job, LLMConfig, Profile } from "@superjob/core";

