/**
 * Token-bucket rate limiter for LLM calls — prevents burst API usage.
 */
export class LLMRateLimiter {
  private tokens: number;
  private lastRefill: number;

  constructor(
    private maxTokens = 10,
    private refillPerMinute = 10
  ) {
    this.tokens = maxTokens;
    this.lastRefill = Date.now();
  }

  private refill() {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    const add = (elapsed / 60_000) * this.refillPerMinute;
    if (add >= 1) {
      this.tokens = Math.min(this.maxTokens, this.tokens + Math.floor(add));
      this.lastRefill = now;
    }
  }

  async acquire(): Promise<boolean> {
    this.refill();
    if (this.tokens <= 0) return false;
    this.tokens--;
    return true;
  }

  get available(): number {
    this.refill();
    return this.tokens;
  }
}

