const SUBMIT_RE = /\b(submit|submit application|send application|complete application|confirm.*submit|finish|apply now|apply)\b/i;
const SAFE_NEXT_RE = /\b(next|continue|review|save and continue)\b/i;

function visible(el: Element): boolean {
  const r = (el as HTMLElement).getBoundingClientRect();
  if (r.width === 0 && r.height === 0) return false;
  const s = getComputedStyle(el as HTMLElement);
  return s.display !== "none" && s.visibility !== "hidden" && Number(s.opacity) > 0;
}

function textOf(el: Element): string {
  if (el instanceof HTMLInputElement) return el.value || el.getAttribute("aria-label") || "";
  return el.getAttribute("aria-label") || el.textContent || "";
}

function isSubmitLike(el: Element): boolean {
  if (document.querySelector('input[type="password"]')) return false;
  if (!visible(el)) return false;
  if (el instanceof HTMLInputElement && el.type === "submit") return true;
  const text = textOf(el).replace(/\s+/g, " ").trim();
  if (!text || SAFE_NEXT_RE.test(text)) return false;
  return SUBMIT_RE.test(text);
}

async function buildPreview(): Promise<string> {
  const audit = await getLastAudit();
  if (!audit) {
    return "Submit this application?\n\nNo recent autofill audit was found. Review the page carefully before submitting.";
  }
  const filled = audit.summary?.filled ?? audit.fieldResults?.filter((f) => f.status === "filled").length ?? 0;
  const skipped = audit.summary?.skipped ?? audit.fieldResults?.filter((f) => f.status === "skipped" || f.status === "failed").length ?? 0;
  const risky = audit.fieldResults?.filter((f) => f.status === "skipped" || f.status === "failed" || /sensitive|needs user|policy|no value/i.test(f.value || f.suggestion || f.reason || "")) ?? [];
  const sample = audit.fieldResults
    ?.filter((f) => f.status === "filled" || f.status === "already_filled")
    .slice(0, 8)
    .map((f) => `• ${f.label}: ${String(f.value ?? "").slice(0, 60)}`)
    .join("\n") ?? "";
  const warnings = risky.slice(0, 5).map((f) => `• ${f.label}: ${f.value || f.suggestion || "needs review"}`).join("\n");
  return [
    "Submit this application?",
    "",
    `Autofill audit: ${filled} filled, ${skipped} skipped.`,
    sample ? `\nFilled sample:\n${sample}` : "",
    warnings ? `\nNeeds review:\n${warnings}` : "",
    "",
    "Click OK only after reviewing the visible page."
  ].filter(Boolean).joi

/** Prevents duplicate concurrent autofill runs (Infosys / SPA spam). */
let busy = false;
let lastRunAt = 0;
const COOLDOWN_MS = 3500;

export function canRunAutofill(): boolean {
  if (busy) return false;
  if (Date.now() - lastRunAt < COOLDOWN_MS) return false;
  return true;
}

export async function withAutofillGuard<T>(fn: () => Promise<T>): Promise<T | null> {
  if (!canRunAutofill()) return null;
  busy = true;
  lastRunAt = Date.now();
  try {
    return await fn();
  } finally {
    busy = false;
  }
}

export function isAutofillBusy(): boolean {
  return busy;
}

