  let labelText = '';
  if (el.id) {
    const labelEl = document.querySelector(`label[for="${el.id}"]`);
    if (labelEl) labelText = labelEl.textContent?.trim() ?? '';
  }
  if (!labelText) labelText = el.name || el.placeholder || '';

  const fieldKey = classifyLabel(labelText);
