    firstName: profile.firstName,
    lastName: profile.lastName,
    email: profile.email,
    phone: profile.phone,
    linkedin: profile.linkedin,
    yearsOfExperience: profile.yearsOfExperience,
    currentCTC: profile.currentCTC,
